function page(p){if(p==='about')return about();if(p==='companies')return companies();if(p==='profile')return profile();if(p==='settings')return settings();if(p==='inicio')return inicioView();if(p==='informe')return hasCompany()?informeView():welcome();if(p==='compare')return compareView();if(p==='home'||p==='panel')return hasCompany()?panelView():welcome();if(p==='company')return hasCompany()?company():welcome();if(!hasCompany()&&!['library'].includes(p))return welcome();if(p==='scope')return scope();if(p==='library')return library();if(p==='equivalences')return equivalences();if(p==='requirements')return requirements();if(p==='controls')return controls();if(p==='current')return current();if(p==='maturity')return maturity();if(p==='needs')return needs();if(p==='actions')return actions();if(p==='evidence')return evidence();if(p==='risks')return risks();if(p==='audits')return audits();if(p==='map')return map();if(p==='detail')return detail();return home()}

function welcome(){return head('BIENVENIDO','Aún no hay ninguna empresa','Crea una organización o importa una exportada para empezar a mapear sus normas.')+`<section class="panel" style="text-align:center"><p>Todo se guarda en este navegador. Puedes eliminar y volver a crear empresas cuando quieras.</p><button onclick="newCompany()">+ Nueva empresa</button> <label class="secondary button" style="cursor:pointer">Importar<input type="file" accept=".json" hidden onchange="importCompany(event)"></label><button class="secondary" onclick="loadDemo()">Cargar empresa de ejemplo</button></section>`}
function companies(){let list=Object.values(db.companies).sort((a,b)=>a.name.localeCompare(b.name));return head('ESPACIO DE TRABAJO','Mis empresas','Cada organización tiene su propio proyecto, evaluación, normativa, evidencias, riesgos y acciones.')+`<section class="companytop"><div><b>${list.length}</b><span> organizaciones guardadas</span></div><button onclick="newCompany()">+ Nueva empresa</button></section><section class="companygrid">${list.map(companyCard).join('')}</section>`}


function companyCard(c){let list=Object.values(db.companies),activeId=c.id===db.activeCompanyId,selected=c.selected.length;return `<article class="companycard ${activeId?'active':''}"><div class="companyhead"><span class="companyavatar">${esc((c.name||'E').slice(0,1).toUpperCase())}</span><div><small>${activeId?'EMPRESA ACTIVA':'ORGANIZACIÓN'}</small><h2>${esc(c.name)}</h2><p>${esc(c.sector||'Sector no definido')} · ${esc(c.size||'Sin tamaño')}</p></div></div><div class="companystats"><span><b>${selected}</b> normas</span><span><b>${Object.keys(c.assess||{}).length}</b> evaluaciones</span><span><b>${(c.actions||[]).length}</b> acciones</span></div><div class="companyactions">${activeId?'<span class="pillok">Activa</span>':`<button onclick="selectCompany('${c.id}')">Abrir empresa</button>`}<button class="secondary" onclick="editCompany('${c.id}')">Editar</button>${true?`<button class="danger" onclick="deleteCompany('${c.id}')">Eliminar</button>`:''}</div></article>`}
function company(){let c=ctx()||blankCompany();return head('ORGANIZACIÓN','Contexto de la empresa','Los datos se guardan dentro de esta organización y alimentan el motor de aplicabilidad y prioridades.')+`<form class="panel form" onsubmit="saveCompany(event)"><div class="grid"><label>Organización<input name="name" required value="${esc(c.name)}"></label><label>Sector<input name="sector" value="${esc(c.sector)}" placeholder="Tecnología, industria, financiero..."></label><label>Tamaño<select name="size"><option ${c.size==='Pequeña'?'selected':''}>Pequeña</option><option ${c.size==='Mediana'||!c.size?'selected':''}>Mediana</option><option ${c.size==='Grande'?'selected':''}>Grande</option></select></label><label>Empleados<input name="employees" type="number" value="${esc(c.employees||'')}"></label><label>Criticidad<select name="criticality"><option value="baja" ${c.criticality==='baja'?'selected':''}>Baja</option><option value="media" ${c.criticality==='media'||!c.criticality?'selected':''}>Media</option><option value="alta" ${c.criticality==='alta'?'selected':''}>Alta</option></select></label><label>Categoría ENS<select name="ensCategory"><option value="">Sin determinar</option>${[['basica','Básica'],['media','Media'],['alta','Alta']].map(o=>`<option value="${o[0]}" ${c.ensCategory===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label><fieldset class="ensdims"><legend>Nivel ENS por dimensión (opcional)</legend>${ENS_DIMS.map(k=>`<label>${ENS_DIM_NAMES[k]}<select name="ensLevel_${k}"><option value="">Según categoría</option>${[['basica','Bajo'],['media','Medio'],['alta','Alto']].map(o=>`<option value="${o[0]}" ${(c.ensLevels||{})[k]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label>`).join('')}</fieldset><label>Clasificación NIS2<select name="nis2Class"><option value="">Sin determinar</option>${[['esencial','Entidad esencial'],['importante','Entidad importante'],['fuera','Fuera de ámbito']].map(o=>`<option value="${o[0]}" ${c.nis2Class===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label><label><input name="doraSimplified" type="checkbox" ${c.doraSimplified?'checked':''}> DORA: marco simplificado (art. 16)</label><label><input name="financial" type="checkbox" ${c.financial?'checked':''}> Entidad financiera</label><label><input name="public" type="checkbox" ${c.public?'checked':''}> Entidad pública</label><label><input name="ai" type="checkbox" ${c.ai?'checked':''}> Utiliza/desarrolla IA</label><label><input name="sensitive" type="checkbox" ${c.sensitive?'checked':''}> Trata información sensible</label></div><div class="target"><label>Nivel objetivo de madurez <b id="tv">${c.target}</b>/5<input name="target" type="range" min="1" max="5" value="${c.target}" oninput="document.getElementById('tv').textContent=this.value"></label></div><button>${c.wizard!=null?'Confirmar y continuar '+icon('arrow-right'):'Guardar contexto y calcular alcance '+icon('arrow-right')}</button><button type="button" class="secondary" onclick="location.hash='companies'">Cancelar</button></form>`}
function scope(){let c=ctx(),r=recommended();return head('02 · NORMATIVA APLICABLE','Define el alcance','Nexus propone marcos a revisar según el contexto. La aplicabilidad jurídica definitiva debe validarse según el caso.')+`<div class="notice"><b>Recomendaciones del motor</b><ul>${(r.reasons.length?r.reasons:['No hay recomendaciones adicionales; selecciona según tu alcance']).map(x=>`<li>${x}</li>`).join('')}</ul></div><section class="fwgrid">${C.frameworks.map(f=>`<label class="fw ${c.selected.includes(f.id)?'sel':''}"><input type="checkbox" ${c.selected.includes(f.id)?'checked':''} onchange="toggle('${f.id}',this.checked)"><div><h2>${esc(f.name)}</h2><p>${esc(f.desc)}</p><small>${C.requirements.filter(r=>r.framework===f.id).length} requisitos · ${C.controls.filter(x=>x.fw.includes(f.id)).length} capacidades relacionadas</small>${r.ids.includes(f.id)&&!c.selected.includes(f.id)?`<em>Recomendada por contexto</em>`:''}</div></label>`).join('')}</section>`}
function library(){let key=new URLSearchParams(location.hash.split('?')[1]||'').get('fw')||'iso27001',tab=new URLSearchParams(location.hash.split('?')[1]||'').get('tab')||'referencias',f=C.frameworks.find(x=>x.id===key),ref=C.references[key],rs=C.requirements.filter(r=>r.framework===key);return head('03 · BIBLIOTECA MULTINORMA','Catálogo ordenado y trazable',`Explora ${esc(f.name)} por referencia, requisito, control y equivalencia. Nexus mantiene el catálogo separado de cada empresa.`)+`<section class="libraryhero"><div><div class="eyebrow">${esc(f.short)}</div><h2>${esc(f.name)}</h2><p>${esc(f.desc)}</p></div><a href="${ref.source}" target="_blank" rel="noopener">Fuente oficial ${icon('arrow-up-right')}</a></section><div class="fwtabs">${C.frameworks.map(x=>`<a class="${x.id===key?'on':''}" href="#library?fw=${x.id}&tab=${tab}">${esc(x.short)}</a>`).join('')}</div><div class="librarytabs"><a class="${tab==='referencias'?'on':''}" href="#library?fw=${key}&tab=referencias">Referencias</a><a class="${tab==='requisitos'?'on':''}" href="#library?fw=${key}&tab=requisitos">Requisitos</a><a class="${tab==='controles'?'on':''}" href="#library?fw=${key}&tab=controles">Controles</a><a class="${tab==='equivalencias'?'on':''}" href="#library?fw=${key}&tab=equivalencias">Equivalencias</a></div>${tab==='referencias'?`<section class="librarylist">${ref.items.map((x,i)=>`<article><div class="refnum">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p></div><span>${String(i+1).padStart(2,'0')}</span></article>`).join('')}</section>`:tab==='requisitos'?`<section class="librarylist">${rs.map((r,i)=>`<article class="clickable" onclick="openDetail('requirement','${r.id}')"><div class="refnum">${r.reference||r.area}</div><div><h3>${r.id} · ${esc(r.title)}</h3><p>${esc(r.description)}</p><small>Control Nexus: ${esc(r.control)}</small></div><span>${icon('arrow-right')}</span></article>`).join('')}</section>`:tab==='controles'?`<section class="librarycontrols">${C.controls.filter(c=>c.fw.includes(key)).map((c,i)=>`<article class="controlrow clickable" onclick="openDetail('control','${c.id}')"><div><small>${c.id} · ${esc(c.area)}</small><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p></div><div class="tags">${c.fw.map(z=>`<span>${fw(z).short}</span>`).join('')}</div></article>`).join('')}</section>`:`<section class="equivmatrix">${C.controls.filter(c=>c.fw.includes(key)).map(c=>{let related=C.requirements.filter(r=>usesCtl(r,c.id));return `<article><div><small>${c.id}</small><h3>${esc(c.name)}</h3><p>${esc(c.reason)}</p></div><div class="eqrefs">${c.fw.map(z=>`<span>${fw(z).short}</span>`).join('')}</div><div class="eqreqs">${related.map(r=>`<a href="#detail?type=requirement&id=${r.id}">${fw(r.framework).short} · ${r.id} · ${esc(r.title)}</a>`).join('')}</div></article>`}).join('')}</section>`}`}
function equivalences(){let c=ctx(),ms=C.mappings.filter(m=>{let r=req(m.requirement);return r&&c.selected.includes(r.framework)}),reviews=c.mappingReviews||{},count=k=>ms.filter(m=>(reviews[m.id]?.status||'Pendiente')===k).length;return head('04 · EQUIVALENCIAS','Matriz de correspondencias revisable','Consulta la relación requisito-control y registra una validación profesional por empresa. Las correspondencias precargadas son propuestas de trabajo, no equivalencias certificadas.')+`<div class="equivhero"><div><b>${ms.length}</b><span>correspondencias activas</span></div><div><b>${count('Pendiente')}</b><span>pendientes de validar</span></div><div><b>${count('Validada')}</b><span>validadas por el equipo</span></div><div><b>${count('Revisar')+count('No equivalente')}</b><span>con observaciones</span></div></div><div class="toolbar mappingtoolbar"><input id="mappingSearch" placeholder="Buscar norma, referencia, requisito o control..." oninput="filterMappings()"><select id="mappingStatusFilter" onchange="filterMappings()"><option value="">Todos los estados</option><option>Pendiente</option><option>Validada</option><option>Revisar</option><option>No equivalente</option></select><button class="secondary" onclick="exportMappingReviews()">Exportar revisión CSV</button></div><div class="mappingnotice"><b>Importante:</b> la referencia indicada orienta la revisión. Antes de validar, comprueba el texto oficial vigente, el alcance de la obligación y si el control cubre todos sus elementos. Una coincidencia funcional no implica conformidad automática.</div><section class="mappingreviewlist">${ms.map(m=>{let r=req(m.requirement),cc=ctl(m.control),rv=reviews[m.id]||{},status=rv.status||'Pendiente',source=C.references[r.framework]?.source||'',strength=m.weight===1?'Potencialmente completa':'Parcial / requiere complemento';return `<article class="mappingreview" data-search="${esc((fw(r.framework).name+' '+r.reference+' '+r.title+' '+cc.name+' '+m.id).toLowerCase())}" data-status="${status}"><div class="mappingtop"><span class="mapfw">${fw(r.framework).short}</span><code>${esc(r.reference||'Referencia por revisar')}</code><span class="reviewbadge ${status==='Validada'?'validated':status==='No equivalente'?'rejected':status==='Revisar'?'needsreview':''}">${status}</span></div><div class="mappingcols"><div><small>REQUISITO / REFERENCIA</small><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><a href="${esc(source)}" target="_blank" rel="noopener">Consultar fuente oficial ${icon('arrow-up-right')}</a></div><div class="mappingarrow">${icon('arrow-left-right')}</div><div><small>CONTROL UNIFICADO</small><h3>${esc(cc.id)} · ${esc(cc.name)}</h3><p>${esc(cc.description)}</p><span class="strength ${m.weight===1?'full':'partial'}">${strength}</span></div></div><details class="mappingedit"><summary>Revisar justificación y estado</summary><div class="mappingeditgrid"><label>Estado de revisión<select onchange="setMappingReview('${m.id}','status',this.value)"><option ${status==='Pendiente'?'selected':''}>Pendiente</option><option ${status==='Validada'?'selected':''}>Validada</option><option ${status==='Revisar'?'selected':''}>Revisar</option><option ${status==='No equivalente'?'selected':''}>No equivalente</option></select></label><label>Revisor<input value="${esc(rv.reviewer||'')}" placeholder="Nombre o rol" onchange="setMappingReview('${m.id}','reviewer',this.value)"></label><label>Fecha de revisión<input type="date" value="${esc(rv.reviewDate||'')}" onchange="setMappingReview('${m.id}','reviewDate',this.value)"></label><label class="mappingnote">Justificación / complemento requerido<textarea rows="3" placeholder="Explica por qué cubre el requisito, qué elementos quedan fuera y qué evidencia se exigirá..." onchange="setMappingReview('${m.id}','note',this.value)">${esc(rv.note||m.rationale||'')}</textarea></label></div><small class="mappingid">ID de trazabilidad: ${esc(m.id)} · Peso de catálogo: ${m.weight??(m.type==='full'?1:0.5)}</small></details></article>`}).join('')}</section>`}
function equivCard(c){let f=c.fw.filter(x=>ctx().selected.includes(x)),rs=activeReqs().filter(r=>usesCtl(r,c.id));return `<article class="equivcard"><div class="equivmain"><div class="eyebrow">${c.id} · ${esc(c.area)}</div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><div class="tags">${f.map(x=>`<span>${fw(x).short}</span>`).join('')}</div></div><div class="equivside"><b>${f.length} norma(s)</b><small>${rs.length} requisito(s) conectado(s)</small><button onclick="openDetail('control','${c.id}')">Ver explicación ${icon('arrow-right')}</button></div></article>`}
function requirements(){let rs=activeReqs(),cov=coverage();return head('05 · REQUISITOS','Universo consolidado de requisitos','Cada requisito tiene una explicación propia, su objetivo, el control relacionado y su estado de cobertura.')+`<div class="needhero"><div><b>${cov.total}</b><small>requisitos aplicables</small></div><div><b>${cov.cubierto}</b><small>cubiertos</small></div><div><b>${cov.parcial}</b><small>parciales</small></div><div><b>${cov.gap}</b><small>gaps</small></div></div><div class="toolbar"><input id="rq" placeholder="Buscar requisito, área o control..." oninput="filterReq()"><select onchange="filterReqState(this.value)"><option value="">Todos</option><option value="cubierto">Cubiertos</option><option value="parcial">Parciales</option><option value="gap">Gap</option><option value="no_aplica">No aplica</option></select></div><section class="reqgrid">${rs.map(requirementCard).join('')}</section>`}
function requirementCard(r){let c=ctl(r.control),s=reqState(r),l=ctx().assess[c.id]?.level??0;return `<article class="reqcard" data-rq="${esc((r.title+' '+r.area+' '+c.name+' '+r.description).toLowerCase())}" data-state="${s}"><div><div class="reqtop"><span>${fw(r.framework).short}</span><b>${r.id}</b></div><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><small>Control unificado: <strong>${c.id} · ${esc(c.name)}</strong></small></div><div class="reqstatus ${s}"><strong>${statusLabel(s)}</strong><span>${l}/5 · objetivo ${ctx().target}</span><button onclick="openDetail('requirement','${r.id}')">Ver explicación</button></div></article>`}
function controls(){let a=activeControls();return head('06 · CONTROLES','Biblioteca de capacidades','Los controles son la unidad de gestión de Nexus: se evalúan una vez y pueden alimentar varios requisitos y normas.')+`<div class="toolbar"><input id="cq" placeholder="Buscar control, área o norma..." oninput="filterCtl()"><select onchange="filterCtlFw(this.value)"><option value="">Todas las normas</option>${ctx().selected.map(x=>`<option value="${x}">${fw(x).short}</option>`).join('')}</select></div><section class="controlgrid">${a.map(controlCard).join('')}</section>`}
function controlCard(c){let l=ctx().assess[c.id]?.level??0,rs=activeReqs().filter(r=>usesCtl(r,c.id)),f=c.fw.filter(x=>ctx().selected.includes(x));return `<article class="controlcard" data-cq="${esc((c.name+' '+c.area+' '+c.description+' '+f.map(x=>fw(x).short).join(' ')).toLowerCase())}" data-fw="${f.join(',')}"><div class="eyebrow">${c.id} · ${esc(c.area)}</div><h2>${esc(c.name)}</h2><p>${esc(c.reason)}</p><div class="tags">${f.map(x=>`<span>${fw(x).short}</span>`).join('')}</div><div class="controlmeta"><span><b>${l}/5</b> madurez</span><span><b>${rs.length}</b> requisitos</span></div><button class="tertiary" onclick="openDetail('control','${c.id}')">Ver control completo ${icon('arrow-right')}</button></article>`}
function current(){let a=activeControls(),c=ctx();return head('07 · SITUACIÓN ACTUAL','¿Dónde estamos?','Evalúa cada capacidad una sola vez. El resultado se reutiliza en todos los requisitos conectados.')+`<div class="toolbar"><input id="q" placeholder="Buscar control..." oninput="filter()"><select onchange="filterLevel(this.value)"><option value="">Todos los niveles</option>${levels.map((x,i)=>`<option value="${i}">${i} · ${x}</option>`).join('')}</select></div><section id="list">${a.map(x=>{let v=c.assess[x.id]||{level:0,owner:'',evidence:''};return `<article class="ctl" data-id="${x.id}" data-q="${esc((x.name+' '+x.area+' '+x.description).toLowerCase())}" data-level="${v.level}"><div class="ctxt"><small>${x.id} · ${esc(x.area)}</small><h2>${esc(x.name)}</h2><p>${esc(x.description)}</p><div>${x.fw.filter(f=>c.selected.includes(f)).map(f=>`<span>${fw(f).short}</span>`).join('')}</div></div><div class="eval"><label>Nivel<select data-field="level" onchange="setA('${x.id}','level',this.value)">${levels.map((z,i)=>`<option value="${i}" ${i===v.level?'selected':''}>${i} · ${z}</option>`).join('')}</select></label><label>Responsable<input data-field="owner" value="${esc(v.owner)}" onchange="setA('${x.id}','owner',this.value)" placeholder="Responsable"></label><label>Observación / evidencia<input data-field="evidence" value="${esc(v.evidence)}" onchange="setA('${x.id}','evidence',this.value)" placeholder="Referencia"></label><button class="save-control" onclick="saveControlEvaluation('${x.id}')">Guardar evaluación</button></div></article>`}).join('')}</section>`}
function maturity(){let c=ctx(),m=mavg();return head('08 · MADUREZ','Medimos para priorizar','La madurez no sustituye una evaluación de conformidad; sirve para ordenar el trabajo y visualizar evolución. Cada nivel es orientativo y debe apoyarse en evidencias.')+`<div class="score"><strong>${m.toFixed(1)}</strong><span>/ 5</span><div><h2>Madurez media</h2><p>Objetivo actual: ${c.target}/5 · ${activeControls().length} capacidades evaluadas</p><div class="bar"><i style="width:${m/5*100}%"></i></div></div></div><section class="panel"><div class="panelhead"><h2>Niveles del modelo</h2><a href="#settings">Configurar modelo ${icon('arrow-right')}</a></div>${levels.map((x,i)=>`<div class="line"><div><b>${i} · ${x}</b><small>${levelCriteria[i]}</small></div>${i===c.target?'<span class="pillok">Objetivo</span>':''}</div>`).join('')}</section>`}
function needs(){let c=ctx(),a=activeControls().filter(x=>(c.assess[x.id]?.level||0)<c.target).sort((x,y)=>priority(y)-priority(x));return head('09 · QUÉ NECESITAS','Del gap a la acción','Nexus prioriza capacidades bajo objetivo y destaca las que pueden cerrar necesidades de varias normas a la vez.')+`<div class="needhero"><div><b>${a.length}</b><small>capacidades pendientes</small></div><div><b>${a.filter(x=>x.fw.filter(f=>c.selected.includes(f)).length>1).length}</b><small>multinorma</small></div><div><b>${c.target}/5</b><small>objetivo</small></div></div><section class="needs">${a.length?a.map(x=>{let p=priority(x),f=x.fw.filter(z=>c.selected.includes(z));return `<article><div><div class="eyebrow">${x.id} · prioridad ${p}</div><h2>${esc(x.name)}</h2><p>${esc(x.description)}</p><div class="tags">${f.map(z=>`<span>${fw(z).short}</span>`).join('')}</div></div><div class="right"><b>${c.assess[x.id]?.level||0}/5</b><small>${f.length} normas afectadas</small><button onclick="make('${x.id}')">Crear acción</button></div></article>`}).join(''):`<div class="empty">No hay controles bajo el nivel objetivo.</div>`}</section>`}
function actions(){let c=ctx();return head('10 · PLAN DE ACCIÓN','Convertimos los gaps en trabajo','Acciones asociadas a capacidades y reutilizables para cerrar necesidades multinorma.')+`<section class="panel"><div class="panelhead"><h2>Acciones</h2><button onclick="auto()">Generar acciones prioritarias</button></div>${c.actions.length?c.actions.map((a,i)=>`<div class="line"><div><b>${esc(a.title)}</b><small>${esc(a.control)} · ${(a.fw||[]).map(esc).join(' · ')}</small><span class="af"><input placeholder="Responsable" value="${esc(a.owner||'')}" onchange="updateActionField(${i},'owner',this.value)"><input type="date" aria-label="Fecha límite" value="${esc(a.due||'')}" onchange="updateActionField(${i},'due',this.value)"><input placeholder="Nota" value="${esc(a.note||'')}" onchange="updateActionField(${i},'note',this.value)">${overdue(a)?'<em class="od">Vencida</em>':''}</span></div><select onchange="updateAction(${i},this.value)">${['Pendiente','En curso','Bloqueada','Completada','Verificada'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="danger" onclick="removeItem('actions',${i})">Eliminar</button></div>`).join(''):`<div class="empty">Todavía no hay acciones. Puedes generarlas desde “Qué necesitas”.</div>`}</section>`}
function evidence(){let c=ctx();return head('11 · EVIDENCIAS','Demostrar lo que existe','Registra responsable, vigencia y revisión. No adjuntes secretos ni datos personales innecesarios; guarda aquí la referencia segura al repositorio documental.')+`<section class="panel"><div class="panelhead"><h2>Nueva evidencia</h2></div><form class="inlineform" onsubmit="addEvidence(event)"><input name="title" required placeholder="Nombre de la evidencia"><select name="control">${activeControls().map(x=>`<option value="${x.id}">${x.id} · ${esc(x.name)}</option>`).join('')}</select><input name="ref" placeholder="Ruta o enlace seguro"><input name="owner" placeholder="Responsable"><input name="reviewDate" type="date" aria-label="Fecha de revisión"><select name="status"><option>Vigente</option><option>Revisar</option><option>Obsoleta</option></select><input name="notes" placeholder="Notas de revisión"><button>Registrar evidencia</button></form></section><section class="panel">${c.evidence.length?c.evidence.map((e,i)=>`<div class="line"><div><b>${esc(e.title)}</b><small>${esc(e.control)} · ${esc(e.owner||'Sin responsable')} · ${esc(e.status||'Vigente')} · Revisar: ${esc(e.reviewDate||'Sin fecha')}<br>${esc(e.ref||'Sin referencia')}${e.notes?' · '+esc(e.notes):''}</small></div><button class="danger" onclick="removeItem('evidence',${i})">Eliminar</button></div>`).join(''):`<div class="empty">Todavía no hay evidencias registradas.</div>`}</section>`}
function risks(){let c=ctx();return head('12 · RIESGOS','Conectar cumplimiento y riesgo','Registra valoración inherente, responsable, tratamiento y estado. La puntuación es una ayuda de priorización, no una valoración automática de riesgo residual.')+`<section class="panel"><form class="inlineform" onsubmit="addRisk(event)"><input name="title" required placeholder="Riesgo identificado"><select name="control">${activeControls().map(x=>`<option value="${x.id}">${x.id} · ${esc(x.name)}</option>`).join('')}</select><label>Impacto<select name="impact">${[1,2,3,4,5].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Probabilidad<select name="likelihood">${[1,2,3,4,5].map(x=>`<option>${x}</option>`).join('')}</select></label><input name="owner" placeholder="Responsable del riesgo"><input name="treatment" placeholder="Tratamiento / respuesta"><select name="status"><option>Abierto</option><option>En tratamiento</option><option>Aceptado</option><option>Cerrado</option></select><button>Registrar riesgo</button></form></section><section class="riskgrid">${c.risks.length?c.risks.map((r,i)=>`<article class="riskcard"><div class="eyebrow">${esc(r.control)} · ${esc(r.status||'Abierto')}</div><h2>${esc(r.title)}</h2><p>Impacto ${r.impact} · Probabilidad ${r.likelihood} · Inherente <b>${r.impact*r.likelihood}/25</b></p><p>Responsable: ${esc(r.owner||'Sin asignar')}<br>Tratamiento: ${esc(r.treatment||'Pendiente de definir')}</p><button class="danger" onclick="removeItem('risks',${i})">Eliminar</button></article>`).join(''):`<div class="empty">Todavía no hay riesgos registrados.</div>`}</section>`}
function audits(){let c=ctx();return head('13 · AUDITORÍA','Comprobar y verificar','Registra alcance, responsable, fecha y resumen de hallazgos. El seguimiento detallado de cada hallazgo puede vincularse a una acción correctiva.')+`<section class="panel"><form class="inlineform" onsubmit="addAudit(event)"><input name="name" required placeholder="Nombre de auditoría"><input name="scope" placeholder="Alcance / normas"><input name="owner" placeholder="Responsable"><input name="date" type="date" aria-label="Fecha de auditoría"><select name="status"><option>Planificada</option><option>En curso</option><option>Finalizada</option></select><input name="findings" placeholder="Resumen de hallazgos"><button>Registrar auditoría</button></form></section><section class="panel">${c.audits.length?c.audits.map((a,i)=>`<div class="line"><div><b>${esc(a.name)}</b><small>${esc(a.scope||'Alcance no indicado')} · ${esc(a.status)} · ${esc(a.owner||'Sin responsable')} · ${esc(a.date||'Sin fecha')}<br>${esc(a.findings||'Sin resumen de hallazgos')}</small></div><button class="danger" onclick="removeItem('audits',${i})">Eliminar</button></div>`).join(''):`<div class="empty">Todavía no hay auditorías registradas.</div>`}</section>`}
function map(){let groups=activeControls().map(x=>({c:x,rs:activeReqs().filter(r=>usesCtl(r,x.id)),l:ctx().assess[x.id]?.level||0}));return head('14 · MAPA MULTINORMA','Una evaluación, múltiples requisitos','La trazabilidad muestra cómo un control puede cerrar varios requisitos y normas.')+`<section class="panel">${groups.map(g=>`<div class="mapblock"><div class="line"><div><b>${g.c.id} · ${esc(g.c.name)}</b><small>${g.rs.length} requisitos relacionados · nivel ${g.l}/5</small></div><div class="tags">${g.c.fw.filter(f=>ctx().selected.includes(f)).map(f=>`<span>${fw(f).short}</span>`).join('')}</div></div><div class="mapreqs">${g.rs.map(r=>`<div><span>${fw(r.framework).short}</span>${esc(r.id)} · ${esc(r.title)}<strong class="${reqState(r)}">${reqState(r)}</strong></div>`).join('')}</div></div>`).join('')}</section>`}
function detail(){let qs=new URLSearchParams(location.hash.split('?')[1]||'');return detailContent(qs.get('type'),qs.get('id'))}
function detailContent(type,id){if(type==='requirement'){let r=req(id);if(!r)return home();let c=ctl(r.control),s=reqState(r);return head('DETALLE · REQUISITO',esc(r.title),`${esc(fw(r.framework).name)} · ${esc(r.id)}`)+`<section class="detail"><div class="detailmain"><div class="eyebrow">${r.id} · ${fw(r.framework).short} · ${esc(r.area)}</div>${reqIntro(r)}${(()=>{const so=ctx().soa[r.id]||{},d=ctx().reqDetails?.[r.id]||{};return `<section class="requirement-edit"><h3>Evaluación y aplicabilidad</h3><p class="muted">Estos datos se guardan para este requisito y esta empresa, independientemente de la norma.</p><label>Aplicabilidad<select id="req-app-${r.id}" onchange="setSoa('${r.id}',this.value)"><option value="auto" ${so.app===undefined||so.app===null?'selected':''}>Automática / pendiente de determinar</option><option value="yes" ${so.app===true?'selected':''}>Aplica</option><option value="no" ${so.app===false?'selected':''}>No aplica</option></select></label><label>Justificación de aplicabilidad<input id="req-just-${r.id}" placeholder="Explica por qué aplica o no aplica" value="${esc(so.note||'')}" onchange="setSoaNote('${r.id}',this.value)"></label><label>Responsable<input id="req-owner-${r.id}" placeholder="Responsable del requisito" value="${esc(d.owner||'')}" onchange="setRequirementField('${r.id}','owner',this.value)"></label><label>Observaciones<textarea id="req-notes-${r.id}" rows="3" placeholder="Situación actual, decisiones, excepciones o tareas pendientes" onchange="setRequirementField('${r.id}','notes',this.value)">${esc(d.notes||'')}</textarea></label><label>Evidencia o referencia documental<input id="req-evidence-${r.id}" placeholder="Ruta, enlace o identificador de evidencia" value="${esc(d.evidence||'')}" onchange="setRequirementField('${r.id}','evidence',this.value)"></label><div class="requirement-save"><button onclick="saveRequirementDetails('${r.id}')">Guardar cambios</button><span>También se guardan automáticamente al salir de cada campo.</span></div></section>`})()}${C.mappings.find(m=>m.requirement===r.id)?.type==='partial'?`<h3>Brecha específica de la norma</h3><p>${esc(C.mappings.find(m=>m.requirement===r.id).rationale)}</p><label><input type="checkbox" ${(ctx().gapclosed||{})[r.id]?'checked':''} onchange="setGap('${r.id}',this.checked)"> Complemento específico implantado</label>`:''}<h3>Estado actual</h3><div class="detailstatus ${s}"><b>${statusLabel(s)}</b><span>Madurez ${ctx().assess[c.id]?.level??0}/5 · objetivo ${ctx().target}/5</span></div></div><aside class="detailaside"><small>TRAZABILIDAD</small><a href="#requirements">${icon('arrow-left')} Volver a requisitos</a><a href="#current">Evaluar control</a><a href="#map">Ver mapa multinorma</a></aside></section>`}let c=ctl(id);if(!c)return home();let rs=activeReqs().filter(r=>usesCtl(r,c.id)),l=ctx().assess[c.id]?.level??0;return head('DETALLE · CONTROL',c.name,`${c.id} · ${esc(c.area)}`)+`<section class="detail"><div class="detailmain"><div class="eyebrow">${c.id} · ${esc(c.area)}</div><h2>¿Qué representa?</h2><p>${esc(c.description)}</p><h3>Explicación</h3><p>${esc(c.reason)}</p><h3>Normas relacionadas</h3><div class="tags">${c.fw.filter(f=>ctx().selected.includes(f)).map(f=>`<span>${fw(f).short}</span>`).join('')}</div><h3>Requisitos conectados (${rs.length})</h3>${rs.map(r=>`<div class="linked"><b>${r.id} · ${esc(r.title)}</b><span>${fw(r.framework).short} · ${statusLabel(reqState(r))}</span><button onclick="openDetail('requirement','${r.id}')">Ver requisito ${icon('arrow-right')}</button></div>`).join('')}<h3>Estado de gestión</h3><div class="detailstatus ${l>=ctx().target?'cubierto':l?'parcial':'gap'}"><b>${l}/5 · ${levels[l]}</b><span>Objetivo ${ctx().target}/5 · ${ctx().assess[c.id]?.evidence?'Evidencia registrada':'Sin evidencia/observación indicada'}</span></div></div><aside class="detailaside"><small>TRAZABILIDAD</small><a href="#controls">${icon('arrow-left')} Volver a controles</a><a href="#current">Evaluar situación actual</a><a href="#needs">Ver necesidades</a><a href="#map">Ver mapa multinorma</a></aside></section>`}
function about(){return head('ACERCA DE','Nexus GRC Lion v1.19.2','Licencia, atribución y créditos del proyecto.')+`<section class="aboutgrid"><article class="aboutcard featured"><div class="eyebrow">EL PROYECTO</div><h2>Nexus GRC Lion</h2><p>Herramienta local-first de gestión de cumplimiento multinorma (GRC). Corre completamente en el navegador; los datos se almacenan en <code>localStorage</code> y no salen del dispositivo.</p><div class="aboutmeta"><span><b>Versión</b> 1.19.2</span><span><b>Motor</b> Rosetta v2.2.0</span><span><b>Frameworks</b> ENS · ISO 27001 · NIS2 · ISO 42001</span></div></article><article class="aboutcard"><div class="eyebrow">LICENCIA</div><h2>GNU General Public License v2</h2><p>Este programa es software libre; puedes redistribuirlo y/o modificarlo bajo los términos de la <b>GNU General Public License</b> publicada por la Free Software Foundation, versión 2 o cualquier versión posterior.</p><p>Se distribuye con la esperanza de que sea útil, pero <b>sin ninguna garantía</b>; ni siquiera la garantía implícita de comerciabilidad o idoneidad para un propósito particular. Consulta la licencia completa para más detalles.</p><a class="buttonlink" href="https://www.gnu.org/licenses/old-licenses/gpl-2.0.html" target="_blank" rel="noopener">Texto completo GPL v2 ${icon('arrow-up-right')}</a></article><article class="aboutcard"><div class="eyebrow">ATRIBUCIÓN</div><h2>Rosetta Multinorma</h2><p>El catálogo de controles unificados, requisitos y correspondencias ponderadas incorporado en este proyecto (<code>app/catalog.js</code>) está derivado de <b>Rosetta Multinorma</b>, desarrollado por <b>heindall92</b> y publicado bajo GNU GPL v2.</p><ul class="aboutlist"><li>Proyecto original: <a href="https://github.com/heindall92/rosetta_multinorma" target="_blank" rel="noopener">github.com/heindall92/rosetta_multinorma</a></li><li>Demo Rosetta: <a href="https://heindall92.github.io/rosetta_multinorma/" target="_blank" rel="noopener">heindall92.github.io/rosetta_multinorma</a></li><li>Versión del catálogo incorporado: v2.2.0</li><li>Modificaciones: adaptación al modelo de datos de Nexus, integración con motor GRC, sin cambio de contenido sustantivo.</li></ul></article><article class="aboutcard"><div class="eyebrow">CONDICIONES DE DISTRIBUCIÓN</div><h2>Si compartes o redistribuyes Nexus</h2><ul class="aboutlist"><li>Debes incluir el código fuente o indicar dónde obtenerlo.</li><li>Debes conservar el fichero <code>NOTICE.md</code> con la atribución a heindall92.</li><li>Debes distribuir bajo la misma licencia GPL v2 (o compatible).</li><li>No puedes añadir restricciones adicionales sobre los derechos que la GPL otorga.</li></ul><p>Para distribución comercial o uso en contextos sensibles, considera obtener asesoramiento legal.</p></article><article class="aboutcard"><div class="eyebrow">AVISO IMPORTANTE</div><h2>Limitaciones de uso</h2><p>Nexus es una herramienta de apoyo a la gestión GRC. <b>No sustituye</b> la auditoría formal, la consultoría especializada ni la certificación oficial. Las evaluaciones generadas son orientativas.</p><p>No almacenes en Nexus secretos, contraseñas completas ni documentos confidenciales íntegros. Los datos quedan en el navegador sin cifrado ni control de acceso.</p></article><article class="aboutcard"><div class="eyebrow">CÓDIGO FUENTE</div><h2>Distribución del código</h2><p>De acuerdo con GPL v2, el código fuente de GRC Nexus debe estar disponible para cualquier receptor de la aplicación. Si has recibido un binario compilado (<code>nexus.html</code>), el distribuidor está obligado a facilitarte el código fuente.</p><a class="buttonlink" href="#settings">Ir a Configuración ${icon('arrow-right')}</a></article></section>`}
function profile(){let roles=['Administrador','Consultor','Auditor','Responsable de seguridad','Responsable de cumplimiento','Dirección','Solo lectura'];return head('PERFIL','Mi perfil','Configura tu identidad, función y preferencias personales dentro de Nexus.')+`<section class="profilehero"><div class="profilebig">${esc(db.profile.avatar||'A')}</div><div><small>PERFIL ACTIVO</small><h2>${esc(db.profile.name||'Administrador')}</h2><p>${esc(db.profile.role||'Usuario')}</p></div></section><form class="panel form" onsubmit="saveProfile(event)"><div class="grid"><label>Nombre<input name="name" value="${esc(db.profile.name)}"></label><label>Rol<select name="role">${roles.map(x=>`<option ${db.profile.role===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Correo<input name="email" type="email" value="${esc(db.profile.email)}"></label><label>Inicial / avatar<input name="avatar" maxlength="2" value="${esc(db.profile.avatar||'A')}"></label></div><div class="profileprefs"><div><b>Preferencias personales</b><span>El aspecto general se configura en Configuración Nexus.</span></div><a href="#settings">Abrir configuración ${icon('arrow-right')}</a></div><button>Guardar perfil</button></form>`}
function settings(){let st=db.settings;return head('SISTEMA','Configuración Nexus','Un centro de preferencias para adaptar Nexus al perfil de trabajo, la organización y el motor GRC.')+`<div class="settingsnav"><a href="#settings" class="on">General</a><a href="#profile">Perfil</a><a href="#company">Empresa</a><a href="#requirements">Catálogo</a></div><section class="settingsgrid"><article class="settingcard featuredsetting"><div class="eyebrow">APARIENCIA</div><h2>Tema y experiencia</h2><p>Elige cómo quieres trabajar con Nexus. Los cambios se aplican inmediatamente.</p><label>Tema<select name="theme" onchange="setPreference('theme',this.value)"><option value="claro" ${st.theme==='claro'?'selected':''}>Claro</option><option value="oscuro" ${st.theme==='oscuro'?'selected':''}>Oscuro</option><option value="sistema" disabled>Según sistema · próximamente</option></select></label><label>Densidad<select name="density" onchange="setPreference('density',this.value)"><option value="comfortable" ${st.density==='comfortable'?'selected':''}>Cómoda</option><option value="standard" ${st.density==='standard'?'selected':''}>Estándar</option><option value="compact" ${st.density==='compact'?'selected':''}>Compacta</option></select></label><label>Barra lateral<select onchange="setPreference('sidebar',this.value)"><option value="expanded" ${st.sidebar==='expanded'?'selected':''}>Expandida</option><option value="compact" ${st.sidebar==='compact'?'selected':''}>Compacta</option></select></label></article><article class="settingcard"><div class="eyebrow">INICIO</div><h2>Experiencia de entrada</h2><p>Decide qué pantalla quieres ver al abrir o volver a Nexus.</p><label>Pantalla inicial<select onchange="setPreference('startPage',this.value)"><option value="panel" ${st.startPage==='panel'?'selected':''}>Panel multinorma</option><option value="inicio" ${st.startPage==='inicio'?'selected':''}>Presentación (Inicio)</option><option value="companies" ${st.startPage==='companies'?'selected':''}>Mis empresas</option></select></label><label class="toggleline"><input type="checkbox" ${st.confirmReset?'checked':''} onchange="setPreference('confirmReset',this.checked)"> Pedir confirmación antes de acciones destructivas</label></article><article class="settingcard"><div class="eyebrow">PERFIL</div><h2>${esc(db.profile.name||'Administrador')}</h2><p>${esc(db.profile.role||'Usuario')} · ${esc(db.profile.email||'Sin correo configurado')}</p><a class="buttonlink" href="#profile">Editar mi perfil ${icon('arrow-right')}</a></article><article class="settingcard"><div class="eyebrow">EMPRESA ACTIVA</div><h2>${esc(ctx()?.name||'Sin empresa')}</h2><p>Contexto, alcance, sector, criticidad y objetivo de madurez de la organización actual.</p><a class="buttonlink" href="#company">Configurar empresa ${icon('arrow-right')}</a><a class="buttonlink" href="#companies">Cambiar empresa ${icon('arrow-right')}</a></article><article class="settingcard"><div class="eyebrow">MOTOR GRC</div><h2>Aplicabilidad y madurez</h2><p>Las recomendaciones se calculan con el contexto de cada empresa y se mantienen separadas por proyecto.</p><label>Nivel objetivo por defecto<select onchange="setPreference('defaultTarget',+this.value)">${[1,2,3,4,5].map(x=>`<option value="${x}" ${st.defaultTarget==x?'selected':''}>${x} · ${levels[x]}</option>`).join('')}</select></label><label class="toggleline"><input type="checkbox" ${st.autoRecommendations?'checked':''} onchange="setPreference('autoRecommendations',this.checked)"> Recomendar automáticamente normativa aplicable</label></article><article class="settingcard"><div class="eyebrow">CATÁLOGO</div><h2>Biblioteca Nexus</h2><p>${C.frameworks.length} frameworks · ${C.requirements.length} requisitos · ${C.controls.length} controles · equivalencias multinorma.</p><a class="buttonlink" href="#library">Biblioteca multinorma ${icon('arrow-right')}</a><a class="buttonlink" href="#requirements">Requisitos ${icon('arrow-right')}</a><a class="buttonlink" href="#controls">Controles ${icon('arrow-right')}</a><a class="buttonlink" href="#equivalences">Equivalencias ${icon('arrow-right')}</a></article><article class="settingcard"><div class="eyebrow">DATOS</div><h2>Importar / exportar</h2><p>Conserva o mueve proyectos completos de Nexus entre entornos.</p><button onclick="exportCompany()">Exportar empresa</button><button class="secondary" onclick="document.getElementById('importFile').click()">Importar empresa</button><input id="importFile" type="file" accept="application/json,.json" hidden onchange="importCompany(event)"></article><article class="settingcard"><div class="eyebrow">ACERCA DE NEXUS</div><h2>GRC Nexus 1.19.2</h2><p>Aplicación local-first para apoyar evaluaciones GRC. Los datos se guardan en este navegador; no hay sincronización ni control de acceso multiusuario. No almacenes secretos ni documentos confidenciales completos.</p><p>Catálogo adaptado parcialmente de Rosetta Multinorma. Licencia del proyecto derivado: GNU GPL v2.0. Consulta README y NOTICE para atribución y límites.</p><a class="buttonlink" href="https://github.com/heindall92/rosetta_multinorma" target="_blank" rel="noopener">Proyecto de referencia ${icon('arrow-up-right')}</a></article><article class="settingcard"><div class="eyebrow">COPIAS DE SEGURIDAD</div><h2>Respaldo completo</h2><p>Exporta todas las empresas, el perfil y las preferencias a un fichero JSON. El respaldo contiene datos de trabajo: guárdalo en una ubicación segura.</p><button onclick="exportBackup()">Descargar respaldo completo</button><label class="fileimportlabel">Restaurar respaldo completo<input type="file" accept="application/json,.json" onchange="restoreBackup(event)"></label><small>La restauración sustituye los datos locales actuales. Se solicita confirmación antes de hacerlo.</small></article><article class="settingcard dangerbox"><div class="eyebrow">MANTENIMIENTO</div><h2>Restablecer proyecto</h2><p>Elimina evaluación, acciones, evidencias, riesgos y auditorías de la empresa activa.</p><button class="danger" onclick="resetCompany()">Restablecer empresa activa</button></article></section>`}
function saveCompany(e){e.preventDefault();let f=new FormData(e.target),c=ctx()||blankCompany();Object.assign(c,{name:f.get('name'),sector:f.get('sector'),size:f.get('size'),employees:f.get('employees'),criticality:f.get('criticality'),financial:f.get('financial')==='on',public:f.get('public')==='on',ai:f.get('ai')==='on',ensCategory:f.get('ensCategory')||'',ensLevels:Object.fromEntries(ENS_DIMS.map(k=>[k,f.get('ensLevel_'+k)]).filter(e=>e[1])),nis2Class:f.get('nis2Class')||'',doraSimplified:f.get('doraSimplified')==='on',sensitive:f.get('sensitive')==='on',target:+f.get('target'),updatedAt:now()});let r=recommended();if(db.settings.autoRecommendations)c.selected=[...new Set([...c.selected,...r.ids])];db.companies[c.id]=c;save();location.hash='scope'}
function newCompany(){let c=blankCompany('Nueva organización');c.target=Number(db.settings.defaultTarget)||3;c.wizard=0;db.companies[c.id]=c;db.activeCompanyId=c.id;save();location.hash==='#company'?render():location.hash='company'}
function selectCompany(id){if(!db.companies[id])return;db.activeCompanyId=id;save();location.hash==='#panel'?render():location.hash='panel'}
function editCompany(id){if(!db.companies[id])return;db.activeCompanyId=id;save();location.hash='company'}
function deleteCompany(id){let c=db.companies[id];if(!c)return;if(db.settings.confirmReset!==false&&!confirm(`¿Eliminar la empresa “${esc(c.name)}” y todos sus datos?`))return;delete db.companies[id];if(db.activeCompanyId===id)db.activeCompanyId=Object.keys(db.companies)[0]||'';save();if(location.hash!=='#companies')location.hash='companies';else render()}
function toggle(id,on){let c=ctx();c.selected=on?[...new Set([...c.selected,id])]:c.selected.filter(x=>x!==id);c.updatedAt=now();save();render()}
function setA(id,k,v){let c=ctx(),cur=c.assess[id]||{level:0,owner:'',evidence:''};if(k==='level'){let n=Number(v);cur.level=Number.isFinite(n)?Math.max(0,Math.min(5,n)):0}else cur[k]=v;c.assess[id]=cur;c.updatedAt=now();save();const card=document.querySelector(`.ctl[data-id="${CSS.escape(id)}"]`);if(card){card.dataset.level=String(cur.level);let sel=card.querySelector('select[data-field="level"]');if(sel&&k==='level')sel.value=String(cur.level)}}
function saveControlEvaluation(id){const card=document.querySelector(`.ctl[data-id="${CSS.escape(id)}"]`);if(!card)return;const get=k=>card.querySelector(`[data-field="${k}"]`);const c=ctx(),old=c.assess[id]||{level:0,owner:'',evidence:''};c.assess[id]={level:Number(get('level')?.value??old.level)||0,owner:get('owner')?.value??old.owner,evidence:get('evidence')?.value??old.evidence};c.updatedAt=now();if(save()){const status=document.getElementById('saveStatus');if(status)status.innerHTML=icon('check')+' Evaluación guardada'}}
function setGap(id,on){let c=ctx();c.gapclosed=c.gapclosed||{};if(on)c.gapclosed[id]=true;else delete c.gapclosed[id];c.updatedAt=now();save();render()}
function setSoa(id,v){let c=ctx();c.soa=c.soa||{};const note=document.getElementById('req-just-'+id)?.value||c.soa[id]?.note||'';if(v==='auto'){if(note)c.soa[id]={app:null,note};else delete c.soa[id]}else c.soa[id]={app:v==='yes',note};c.updatedAt=now();save();refreshDetailStatus(id)}
function setSoaNote(id,value){let c=ctx();c.soa=c.soa||{};const selected=document.getElementById('req-app-'+id)?.value||'auto';const app=selected==='auto'?null:selected==='yes';const note=String(value??'').slice(0,2000);if(selected==='auto'&&!note)delete c.soa[id];else c.soa[id]={app,note};c.updatedAt=now();save()}
function setRequirementField(id,field,value){if(!['owner','notes','evidence'].includes(field))return;let c=ctx();c.reqDetails=c.reqDetails||{};c.reqDetails[id]=c.reqDetails[id]||{owner:'',notes:'',evidence:''};c.reqDetails[id][field]=String(value??'').slice(0,4000);c.updatedAt=now();save()}
function saveRequirementDetails(id){const c=ctx();const app=document.getElementById('req-app-'+id)?.value||'auto';const note=document.getElementById('req-just-'+id)?.value||'';if(app==='auto'){if(note)c.soa[id]={app:null,note};else delete c.soa[id]}else c.soa[id]={app:app==='yes',note};c.reqDetails=c.reqDetails||{};c.reqDetails[id]={owner:document.getElementById('req-owner-'+id)?.value||'',notes:document.getElementById('req-notes-'+id)?.value||'',evidence:document.getElementById('req-evidence-'+id)?.value||''};c.updatedAt=now();if(save()){const el=document.getElementById('saveStatus');if(el){el.className='save-status saved';el.innerHTML=icon('check')+' Cambios guardados';}render()}}
function refreshDetailStatus(id){const status=document.querySelector('.detailstatus');const r=req(id);if(status&&r){const s=reqState(r);status.className='detailstatus '+s;const b=status.querySelector('b');if(b)b.textContent=statusLabel(s)}}
function setMappingReview(id,field,value){let c=ctx();c.mappingReviews=c.mappingReviews||{};let r=c.mappingReviews[id]||{status:'Pendiente',note:'',reviewer:'',reviewDate:''};if(!['status','note','reviewer','reviewDate'].includes(field))return;r[field]=String(value??'').slice(0,2000);if(field==='status'&&value==='Validada'&&!r.reviewDate)r.reviewDate=new Date().toISOString().slice(0,10);c.mappingReviews[id]=r;save();render()}function filterMappings(){let q=(document.getElementById('mappingSearch')?.value||'').toLowerCase(),st=document.getElementById('mappingStatusFilter')?.value||'';document.querySelectorAll('.mappingreview').forEach(x=>x.style.display=(!q||x.dataset.search.includes(q))&&(!st||x.dataset.status===st)?'':'none')}function exportMappingReviews(){let c=ctx(),rows=[['Empresa','ID correspondencia','Norma','Referencia','Requisito','Control','Estado','Revisor','Fecha revisión','Justificación']];C.mappings.filter(m=>{let r=req(m.requirement);return r&&c.selected.includes(r.framework)}).forEach(m=>{let r=req(m.requirement),cc=ctl(m.control),v=c.mappingReviews?.[m.id]||{};rows.push([c.name,m.id,fw(r.framework).name,r.reference,r.title,cc.name,v.status||'Pendiente',v.reviewer||'',v.reviewDate||'',v.note||m.rationale||''])});const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='matriz-correspondencias-'+(c.name||'empresa').replace(/[^a-z0-9_-]+/gi,'-')+'.csv';a.click();URL.revokeObjectURL(url)}
function filter(){let q=(document.getElementById('q')?.value||'').toLowerCase();document.querySelectorAll('.ctl').forEach(x=>x.style.display=x.dataset.q.includes(q)?'':'none')}function filterLevel(v){document.querySelectorAll('.ctl').forEach(x=>x.style.display=!v||x.dataset.level===v?'':'none')}function filterReq(){let q=(document.getElementById('rq')?.value||'').toLowerCase();document.querySelectorAll('.reqcard').forEach(x=>x.style.display=x.dataset.rq.includes(q)?'':'none')}function filterReqState(v){document.querySelectorAll('.reqcard').forEach(x=>x.style.display=!v||x.dataset.state===v?'':'none')}function filterCtl(){let q=(document.getElementById('cq')?.value||'').toLowerCase();document.querySelectorAll('.controlcard').forEach(x=>x.style.display=x.dataset.cq.includes(q)?'':'none')}function filterCtlFw(v){document.querySelectorAll('.controlcard').forEach(x=>x.style.display=!v||x.dataset.fw.split(',').includes(v)?'':'none')}
function make(id){let c=ctx(),x=ctl(id);if(!c.actions.some(a=>a.control===id)){c.actions.push({title:'Implantar / mejorar '+x.name,control:id,fw:x.fw.filter(z=>c.selected.includes(z)).map(z=>fw(z).short),status:'Pendiente'})}save();location.hash='actions'}function auto(){let c=ctx();activeControls().filter(x=>(c.assess[x.id]?.level||0)<c.target).sort((a,b)=>priority(b)-priority(a)).forEach(x=>{if(!c.actions.some(a=>a.control===x.id))c.actions.push({title:'Implantar / mejorar '+x.name,control:x.id,fw:x.fw.filter(z=>c.selected.includes(z)).map(z=>fw(z).short),status:'Pendiente'})});save();render()}function updateAction(i,v){ctx().actions[i].status=v;save();render()}function updateActionField(i,k,v){if(!ctx().actions[i]||!['owner','due','note'].includes(k))return;ctx().actions[i][k]=String(v??'').slice(0,2000);save()}
function addEvidence(e){e.preventDefault();let f=new FormData(e.target);ctx().evidence.push({title:f.get('title'),control:f.get('control'),ref:f.get('ref'),owner:f.get('owner'),reviewDate:f.get('reviewDate'),status:f.get('status'),notes:f.get('notes')});save();render()}function addRisk(e){e.preventDefault();let f=new FormData(e.target);ctx().risks.push({title:f.get('title'),control:f.get('control'),impact:+f.get('impact'),likelihood:+f.get('likelihood'),owner:f.get('owner'),treatment:f.get('treatment'),status:f.get('status')});save();render()}function addAudit(e){e.preventDefault();let f=new FormData(e.target);ctx().audits.push({name:f.get('name'),scope:f.get('scope'),owner:f.get('owner'),date:f.get('date'),findings:f.get('findings'),status:f.get('status')});save();render()}function removeItem(k,i){ctx()[k].splice(i,1);save();render()}
function saveProfile(e){e.preventDefault();let f=new FormData(e.target);db.profile={...db.profile,name:f.get('name')||'Administrador',role:f.get('role')||'Usuario',email:f.get('email')||'',avatar:(f.get('avatar')||f.get('name')||'A').slice(0,2).toUpperCase()};save();render()}function saveSettings(e){e.preventDefault();let f=new FormData(e.target);db.settings.defaultTarget=+f.get('defaultTarget');db.settings.autoRecommendations=f.get('autoRecommendations')==='on';save();render()}function setPreference(k,v){db.settings[k]=v;save();render()}function cycleTheme(){db.settings.theme=db.settings.theme==='oscuro'?'claro':'oscuro';save();render()}function toggleSetting(k,v){db.settings[k]=v;save();render()}
function buildBackupPayload(){return {type:'grc-nexus-backup',app:'Nexus GRC Lion',appVersion:'1.19.1',schemaVersion:19,exportedAt:new Date().toISOString(),activeCompanyId:db.activeCompanyId,profile:db.profile,settings:db.settings,companies:db.companies};}
function exportBackup(){
 const payload=buildBackupPayload();
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='grc-nexus-respaldo-'+new Date().toISOString().slice(0,10)+'.grcnexus-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function restoreBackup(e){
 const file=e.target.files?.[0];if(!file)return;
 if(file.size>10*1024*1024){alert('El respaldo supera el límite de 10 MB.');e.target.value='';return}
 const reader=new FileReader();reader.onload=()=>{
  const previous=db;
  try{
   const x=JSON.parse(String(reader.result||''));
   if(x?.type!=='grc-nexus-backup'||!x.companies||typeof x.companies!=='object'||Array.isArray(x.companies))throw new Error('Formato no válido');
   const entries=Object.entries(x.companies);if(!entries.length||entries.length>200)throw new Error('Número de empresas no válido');
   if(!confirm('Se reemplazarán los datos locales actuales por el respaldo seleccionado. Antes de continuar, asegúrate de haber exportado una copia de seguridad de lo que tienes ahora. ¿Continuar?')){e.target.value='';return}
   const companies={},idMap={};
   for(const [oldId,value] of entries){const c=normalizeCompany(value);const id='org-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);idMap[oldId]=id;c.id=id;companies[id]=c;}
   const oldActive=x.activeCompanyId,activeCompanyId=idMap[oldActive]||Object.keys(companies)[0];
   const safeProfile=x.profile&&typeof x.profile==='object'?x.profile:{};
   const safeSettings=x.settings&&typeof x.settings==='object'?x.settings:{};
   db={version:19,activeCompanyId,companies,profile:{name:String(safeProfile.name||'Administrador').slice(0,100),role:String(safeProfile.role||'Usuario').slice(0,100),email:String(safeProfile.email||'').slice(0,200),avatar:String(safeProfile.avatar||'A').slice(0,2)},settings:{theme:['claro','oscuro'].includes(safeSettings.theme)?safeSettings.theme:'claro',language:safeSettings.language==='en'?'en':'es',autoRecommendations:safeSettings.autoRecommendations!==false,defaultTarget:Math.max(1,Math.min(5,Number(safeSettings.defaultTarget)||3)),density:['comfortable','standard','compact'].includes(safeSettings.density)?safeSettings.density:'comfortable',sidebar:['expanded','compact'].includes(safeSettings.sidebar)?safeSettings.sidebar:'expanded',startPage:['panel','companies','inicio'].includes(safeSettings.startPage)?safeSettings.startPage:'panel',accent:'gold',confirmReset:safeSettings.confirmReset!==false}};
   if(!save()){db=previous;return}location.hash='#companies';render();alert('Respaldo restaurado. Se han importado '+entries.length+' empresas.');
  }catch(err){db=previous;alert('No se ha podido restaurar el respaldo: el archivo no es válido o está dañado. No se han sustituido los datos actuales.');}
  finally{e.target.value=''}
 };reader.onerror=()=>{alert('No se pudo leer el archivo.');e.target.value=''};reader.readAsText(file);
}
function exportCompany(){let c=ctx(),blob=new Blob([JSON.stringify({type:'grc-nexus-company',version:19,company:c},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(c.name||'empresa').replace(/[^a-z0-9áéíóúüñ]+/gi,'-')+'.grcnexus.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function importCompany(e){let file=e.target.files?.[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result),c=normalizeCompany(x.company||x);c.id='org-'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);c.name=(c.name||'Empresa importada')+' · importada';db.companies[c.id]=c;db.activeCompanyId=c.id;save();location.hash='companies'}catch(err){alert('El archivo no parece un proyecto de Nexus GRC Lion válido.')}};reader.readAsText(file)}
